//! Every outcome michi renders composes into one `AgentResponse` (docs/spec/06-decisions.md, "Outcomes compose into
//! one response"): `DomainError`, `PartialSuccess`, `StatusResponse`, `Pipeline` and `already_done` become sections or
//! the error block of the response, and render through its one writer on every surface. Each probe below was
//! impossible before: the type had its own document, and two documents could not be joined into one valid one.

use michi_core::kv::{KvItem, KvValue};
use michi_core::pipeline::{Pipeline, PipelineStep, SkipReason, StepStatus};
use michi_core::toon::Value;
use michi_core::{
    AgentResponse, Audience, BudgetSummary, CompletedOp, DomainError, ErrorCode, FailedOp, Health, OutputFormat,

// ---- Finding 5: hint sources compose ----

fn status() -> StatusResponse {
    StatusResponse::new(
        "tool",
        "desc",
        vec![StatusItem::new("index", KvValue::Text("ready".into())).health(Health::Ok)],
    )
    .hints(vec!["call get_status for detail".into()])
}

#[test]
fn hints_replaces_only_the_callers_own_hints() {
    let r = AgentResponse::new("t").hint("dropped").status(status()).hints(vec![Hint::new("mine")]);
    let help = r.render_hints_only();
    assert_eq!(help, "help[2]: call get_status for detail,mine");
    let v = json(&r);
    assert_eq!(v["hints"], serde_json::json!(["call get_status for detail", "mine"]));
    assert!(r.render(OutputFormat::Text).ends_with(&help));
}

#[test]
fn hints_keeps_the_showing_n_of_m_line_of_a_cut_section() {
    let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
    let r = AgentResponse::new("t")
        .truncated_section("t", fields(&["n"]), &outcome, |n| vec![Value::Int(*n)], "pass --limit 4")
        .hints(vec![Hint::new("mine")]);
    assert_eq!(
        r.render(OutputFormat::Text),
        "t[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[2]: showing 2 of 4; pass --limit 4,mine"
    );
}
}

fn status(n: usize) -> michi_core::StatusResponse {
    use michi_core::{Health, Hint, StatusItem, StatusResponse};
    let items = (0..n)
        .map(|i| {
            StatusItem::new(format!("check{i}"), KvValue::Float(i as f64 / 7.0, 2))
                .health(Health::Degraded(format!("slow {i}")))
        })
        .collect();
    StatusResponse::new("tool", "does things", items)
        .hints((0..n).map(|i| Hint::new(format!("look at check{i}"))).collect())
}

#[test]
fn status_composes_and_renders_linearly() {
        "AgentResponse mixed outcomes",
        500,
        |n| (causes_error(n), ops(n), status(n), pipeline(n), n),
        |(e, ps, s, p, n)| {
            let rows = (0..*n).map(|i| vec![Value::Int(i as i64), Value::from(format!("result {i}"))]).collect();
            let mut r = AgentResponse::new("batch")
                .error(e.clone())
                .section(Section::toon("results", vec!["n".into(), "title".into()], rows).total_count(Some(n * 2)))
                .partial_success("ops", ps.clone())
                .status(s.clone())
                .pipeline("step", p.clone())
                .budget(BudgetSummary::new().tokens_used(1));
            r = r.hints((0..*n).map(|i| Hint::new(format!("hint {i}"))).collect());
            for i in 0..*n {
                r = r.hint(format!("more {i}")).recovery_hint(RecoveryHint::new(format!("tool{i}")));
            }
            black_box(r.render(OutputFormat::Text));

